DROP TABLE IF EXISTS `bonos_semanas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bonos_semanas` (
  `clave` varchar(100) NOT NULL,
  `orden` bigint(20) NOT NULL AUTO_INCREMENT,
  `semana` int(11) DEFAULT NULL,
  `periodo_ini` varchar(50) DEFAULT NULL,
  `periodo_fin` varchar(50) DEFAULT NULL,
  `fecha` varchar(50) DEFAULT NULL,
  `celdas` longtext DEFAULT NULL,
  `guardado` datetime(3) DEFAULT NULL,
  `extra` longtext DEFAULT NULL,
  PRIMARY KEY (`clave`),
  UNIQUE KEY `uq_bs_orden` (`orden`),
  CONSTRAINT `chk_bs_celdas` CHECK (`celdas` is null or json_valid(`celdas`)),
  CONSTRAINT `chk_bs_extra` CHECK (`extra` is null or json_valid(`extra`))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
