  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) NOT NULL,
  `username` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `rol` varchar(40) NOT NULL,
  `numero_empleado` varchar(50) DEFAULT NULL COMMENT 'Numero de empleado del tecnico (mismo que usa koide en repair_started_by / closed_by)',
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_usuarios_username` (`username`),
  CONSTRAINT `chk_usuarios_rol` CHECK (`rol` in ('mantenimiento_admin','mantenimiento_op'))
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
